import asyncio

async def call_with_timeout(session, name, args, timeout_s=30):
    try:
        return await asyncio.wait_for(
            session.call_tool(name, args), timeout=timeout_s
        )
    except asyncio.TimeoutError:
        return {"error": "tool_timeout", "tool": name}

try:
    result = await mcp_session.call_tool(name, args)
    history.append({"role": "tool", "content": result})
except MCPToolError as e:
    history.append({
        "role": "tool",
        "content": f"Tool '{name}' failed: {e.message}. "
                    f"Consider different arguments or a different tool."
    })

import time, logging

async def call_tool_logged(session, name, args):
    start = time.time()
    try:
        result = await session.call_tool(name, args)
        logging.info("tool_call", extra={
            "tool": name, "args": args,
            "latency_ms": (time.time() - start) * 1000, "ok": True,
        })
        return result
    except Exception as e:
        logging.error("tool_call_failed", extra={
            "tool": name, "args": args, "error": str(e),
        })
        raise

async def call_with_progress(session, name, args, on_progress):
    async with session.progress_listener(on_progress):
        return await session.call_tool(name, args)

def on_progress(update):
    print(f"{update.tool}: {update.percent}% - {update.message}")

